const betaDepartments=["Copy","Design","Video","Strategy","Media","PR","Client Solutions","Business Development","Operations","Founder's Office","Creative Innovation"];
import {S} from './strings.js';
const parseDay=v=>/^\d{4}-\d{2}-\d{2}$/.test(v)?new Date(v+'T12:00:00'):new Date(v);
const skillText=v=>{try{const a=JSON.parse(v);return Array.isArray(a)?a.join(', '):v}catch{return v}};
const app = document.querySelector('#app');
const modalRoot = document.querySelector('#modal-root');
const toastRoot = document.querySelector('#toast-root');
const beta=window.AGENCY_BETA;
let state={users:[],devUsers:[],brands:[],projects:[],tasks:[],activity:[],profileRequests:[],messages:[],scopeDepartments:[],currentUserId:0,sessionUserId:0};
let projectTab = 'overview';
let departmentFilter = 'All';
let calendarView = 'month';
let calendarDepartment = 'All';
let calendarDate = new Date();
let messageSearch = '';
let bandwidthDepartment = '';
let modalReturnFocus = null;
let modalDirty = false;
let presenceUserIds = new Set();
let readingThreadKey = '';

const esc = value => String(value ?? '').replace(/[&<>'"]/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));
const user = id => state.users.find(u => u.id === Number(id)) || (state.historicalUsers||[]).find(u=>u.id===Number(id)) || state.devUsers.find(u => u.id === Number(id));
const brand = id => state.brands.find(b => b.id === Number(id));
const project = id => state.projects.find(p => p.id === Number(id));
const task = id => state.tasks.find(t => t.id === Number(id));
const currentUser = () => state.users.find(u=>u.id===state.currentUserId) || user(state.currentUserId) || state.users[0];
const isManager = () => ['MANAGER','TEAM LEAD','CREATIVE DIRECTOR','DEPARTMENT HEAD','CLIENT SOLUTIONS','LEADERSHIP','SUPER ADMIN'].includes(currentUser().role);
const isReviewer = t => !(t.versions?.[0]?.submitter_id===state.currentUserId) && isReviewerRole(t);
const isReviewerRole = t => Number(t.reviewer_id) === state.currentUserId || ['TEAM LEAD','MANAGER','CREATIVE DIRECTOR','DEPARTMENT HEAD','SUPER ADMIN'].includes(currentUser().role);
const initials = u => u?.initials || '—';
const safeColor = c => /^#[0-9a-f]{3,8}$/i.test(String(c||'')) ? c : '#ddd';
const avatar = (u, cls='') => `<span class="avatar ${cls}" style="background:${safeColor(u?.color)}">${esc(initials(u))}</span>`;
const deptClass = d => `dept-${String(d||'other').toLowerCase().replace(/[^a-z0-9]+/g,'-')}`;
const personLink = (u, contextProjectId=null, label='') => u ? `<button class="person-link" data-person="${u.id}" ${contextProjectId?`data-project-context="${contextProjectId}"`:''}>${avatar(u,'sm')}<span>${esc(label||u.name)}</span></button>` : '<span>Unassigned</span>';
const status = value => `<span class="status" data-status="${esc(value)}">${esc(value)}</span>`;
const priority = value => `<span class="priority" data-value="${esc(value)}">${esc(value)}</span>`;
const rating = (value,label='Rating') => `<span class="rating rating-${String(value||'C').replace('+','plus').toLowerCase()}" title="${esc(label)}">${esc(value||'C')}</span>`;
const ratingDescriptions={
  'A+':'Flagship or business-critical work. Highest priority and close leadership attention.',
  'A':'High-priority work with significant client or business impact.',
  'B':'Standard planned work with normal delivery priority.',
  'C':'Routine, lower-risk work that can follow standard scheduling.'
};
const ratingHelp=(kind,value)=>`<small class="rating-help" data-rating-help>${esc(kind)} rating ${esc(value)} — ${esc(ratingDescriptions[value]||ratingDescriptions.B)}</small>`;
const infoTip=(text,label='About this section')=>{if(!text)return '';const id=`tip-${Math.random().toString(36).slice(2)}`;return `<span class="info-tip"><button type="button" class="info-tip-trigger" aria-label="${esc(label)}" aria-describedby="${id}">i</button><span class="info-tip-content" id="${id}" role="tooltip">${esc(text)}</span></span>`;};
const alphaPeople=people=>people.slice().sort((a,b)=>a.name.localeCompare(b.name,undefined,{sensitivity:'base'}));
const brandLabel = b => b ? `<span class="brand-label">${rating(b.rating,'Brand rating')}<span>${esc(b.name)}</span></span>` : '<span>Brand</span>';
const presence = u => `<span class="presence ${u?.is_online?'online':'offline'}"><i></i>${u?.is_online?'Online now':'Not active now'}</span>`;
const route = () => (location.hash || '#/home').slice(2).split('/').filter(Boolean);
const dueClass = iso => { const d=new Date(iso), now=new Date(); if(d<now) return 'overdue'; return d.toDateString()===now.toDateString()?'today':''; };
const taskDueClass = t => ['Complete','Cancelled'].includes(t.status)?'':dueClass(t.deadline);
const fmtDate = (iso, opts={}) => iso ? new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',...opts}).format(parseDay(iso)).toUpperCase() : '—';
const fmtDateTime = iso => iso ? new Intl.DateTimeFormat('en-IN',{weekday:'short',day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}).format(parseDay(iso)) : '—';
const localDateInput = value => { const d=new Date(value); return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16); };
const fmtTime = iso => iso ? new Intl.DateTimeFormat('en-IN',{hour:'numeric',minute:'2-digit'}).format(parseDay(iso)) : '—';
const relative = iso => {
  const ms=new Date(iso)-new Date(), hours=Math.round(ms/36e5);
  if(ms<0){const m=Math.round(-ms/6e4);return m<60?`${m}m late`:m<2880?`${Math.round(m/60)}h late`:`${Math.round(m/1440)}d late`;} if(hours<24) return `in ${hours}h`; return `in ${Math.ceil(hours/24)}d`;
};
const projectTasks = id => state.tasks.filter(t => t.project_id === Number(id));
const progress = id => { const ts=projectTasks(id); return ts.length ? Math.round(ts.filter(t=>['Complete'].includes(t.status)).length/ts.length*100) : 0; };
const activityFor = (key,id) => state.activity.filter(a => Number(a[key]) === Number(id));
const userName = id => user(id)?.name || 'Unassigned';
const projectName = id => project(id)?.name || 'Unknown project';
const brandForTask = t => brand(project(t.project_id)?.brand_id);
const activeTasks = ts => ts.filter(t=>!['Complete','Cancelled'].includes(t.status));
const safeHref = value => { try { const raw=String(value||'').trim(); if(!raw) return ''; const url=new URL(raw,location.href); return url.protocol==='https:'||url.origin===location.origin?url.href:''; } catch { return ''; } };
const deadlineBuffer = p => { const a=new Date(p.internal_deadline),b=new Date(p.client_deadline); return Number.isFinite(a.getTime())&&Number.isFinite(b.getTime())?Math.max(0,Math.ceil((b-a)/864e5)):0; };
const approvalJourney = t => { const steps=['Work','Internal','CS','Client','Final'],stage=String(t.stage||'').toLowerCase();const idx=stage==='final'?4:stage.includes('client')?3:stage.includes('cs')?2:stage.includes('review')?1:0;let active=t.status==='Complete'?5:t.status==='Approved'?Math.min(4,idx+1):idx;return `<div class="approval-journey" aria-label="Approval journey">${steps.map((s,i)=>`<span class="${i<active?'done':i===active?'active':''}"><i>${i+1}</i>${s}</span>`).join('')}</div>`; };
const workloadFor = (u, tasks=state.tasks) => {
  const active=activeTasks(tasks.filter(t=>t.owner_id===u.id)),due=active.filter(t=>taskDueClass(t)==='today').length,priority=active.filter(t=>['High','Urgent'].includes(t.priority)).length,needs=active.filter(t=>t.status==='Needs Changes').length,blocked=active.filter(t=>t.status==='Blocked').length;
  const hours=active.reduce((sum,t)=>sum+Number(t.estimate_hours||2),0),available=Number(u.capacity_hours||40),pct=Math.min(125,Math.round(hours/Math.max(1,available)*100));
  return {active:active.length,due,priority,needs,blocked,hours,available,label:S.capLabel(pct),pct:Math.min(100,pct)};
};
const workloadMeta = w => [w.hours&&`${w.hours}h estimated`,`${w.available}h available`,w.due&&`${w.due} due today`,w.needs&&`${w.needs} needs changes`,w.blocked&&`${w.blocked} blocked`].filter(Boolean).join(' · ')||'No active work';

function peopleBandwidthRows(people,tasks){
  return `<div class="people-bandwidth">${alphaPeople(people).map(u=>{const w=workloadFor(u,tasks);return `<article class="person-bandwidth ${deptClass(u.department)}"><div class="person-bandwidth-name">${avatar(u,'sm')}<span><b>${esc(u.name)}</b><small>${esc(u.title)}</small></span></div><div class="person-bandwidth-work"><span>${esc(workloadMeta(w))}</span><div class="progress"><span style="width:${w.pct}%"></span></div></div><strong>${w.label}</strong></article>`}).join('')||'<div class="empty">No people in this scope.</div>'}</div>`;
}

function bandwidthView(tasks){
  const me=currentUser(),orgWide=['LEADERSHIP','SUPER ADMIN'].includes(me.role),multiScope=me.role==='CREATIVE DIRECTOR';
  if(orgWide||multiScope){
    const departments=orgWide?[...new Set(state.users.map(u=>u.department))].sort():(state.scopeDepartments||[]).slice().sort();
    if(bandwidthDepartment&&departments.includes(bandwidthDepartment)){
      const people=state.users.filter(u=>u.department===bandwidthDepartment);
      return `<section class="panel dark-panel bandwidth-panel"><div class="panel-head"><button class="bandwidth-back" data-bandwidth-back>Back</button><h2>${esc(bandwidthDepartment)} team capacity</h2></div><div class="panel-body">${peopleBandwidthRows(people,tasks)}</div></section>`;
    }
    return `<section class="panel dark-panel bandwidth-panel"><div class="panel-head"><h2>Team capacity</h2></div><div class="panel-body">${departments.map(d=>{const people=state.users.filter(u=>u.department===d),work=activeTasks(tasks.filter(t=>t.department===d)),aggregate=people.reduce((n,u)=>n+workloadFor(u,tasks).pct,0)/Math.max(1,people.length),label=S.capLabel(aggregate);return `<button class="department-bandwidth ${deptClass(d)}" data-bandwidth-dept="${esc(d)}"><span><b>${esc(d)}</b><small>${work.reduce((sum,t)=>sum+Number(t.estimate_hours||2),0)}h estimated · ${people.length} ${people.length===1?'person':'people'}</small></span><div class="progress"><span style="width:${Math.min(100,Math.round(aggregate))}%"></span></div><strong>${label}</strong></button>`}).join('')}<p class="bandwidth-note">${S.capNote}</p></div></section>`;
  }
  if(['MANAGER','TEAM LEAD','DEPARTMENT HEAD'].includes(me.role)){
    const people=state.users.filter(u=>u.department===me.department&&(me.role==='DEPARTMENT HEAD'||u.id===me.id||u.manager_id===me.id));
    return `<section class="panel dark-panel bandwidth-panel"><div class="panel-head"><h2>${esc(me.department)} team capacity</h2></div><div class="panel-body">${peopleBandwidthRows(people,tasks)}<p class="bandwidth-note">${S.capNote}</p></div></section>`;
  }
  return `<section class="panel dark-panel bandwidth-panel"><div class="panel-head"><h2>My capacity</h2></div><div class="panel-body">${peopleBandwidthRows([me],tasks)}<p class="bandwidth-note">${S.capNote}</p></div></section>`;
}

async function api(path,options={}){return beta.invoke(path,options);}
function applyLivePresence(){state.users.forEach(u=>u.is_online=presenceUserIds.has(Number(u.id)));(state.assignmentUsers||[]).forEach(u=>u.is_online=presenceUserIds.has(Number(u.id)));}
async function refresh(renderNow=true){state=await api('/api/bootstrap');applyLivePresence();if(state.sessionUserId&&!beta.presenceStarted)beta.startPresence(state.sessionUserId,ids=>{presenceUserIds=new Set(ids.map(Number));applyLivePresence();if(state.sessionUserId&&!modalRoot.innerHTML)render();}).catch(()=>{});if(renderNow)render();}
function go(path) { location.hash=`#/${path}`; }
function toast(message) { const el=document.createElement('div'); el.className='toast'; el.textContent=message; toastRoot.append(el); setTimeout(()=>el.remove(),2600); }
function celebrate() { const box=document.createElement('div'); box.className='celebrate'; for(let i=0;i<45;i++){const p=document.createElement('i');p.className='confetti';p.style.left=`${Math.random()*100}%`;p.style.setProperty('--x',`${(Math.random()-.5)*300}px`);p.style.setProperty('--c',['#15adc2','#ef4754','#536fae','#fcbe47','#35c98a'][i%5]);p.style.animationDelay=`${Math.random()*.35}s`;box.append(p)} document.body.append(box);setTimeout(()=>box.remove(),1800); }

function departmentFilters() {
  if((state.scopeDepartments||[]).length<2) return `<div class="scope-note"><span class="dept-marker ${deptClass(currentUser().department)}"></span>${esc(currentUser().department)} scope + assigned projects</div>`;
  return `<div class="dept-filters"><button class="dept-filter ${departmentFilter==='All'?'active':''}" data-department="All">All</button>${state.scopeDepartments.slice().sort().map(d=>`<button class="dept-filter ${departmentFilter===d?'active':''} ${deptClass(d)}" data-department="${esc(d)}"><span class="dept-marker"></span>${esc(d)}</button>`).join('')}</div>`;
}
const filteredTasks = tasks => departmentFilter==='All' ? tasks : tasks.filter(t=>t.department===departmentFilter);

function shell(content, active='home') {
  const me=currentUser();
  const requestCount=state.profileRequests.filter(r=>r.status==='Pending'&&r.approver_id===state.currentUserId).length;
  const unread=state.messages.filter(m=>m.recipient_id===state.currentUserId&&!m.read_at).length;
  const nav=[['home','Home'],['my-work','My Work'],['projects','Projects'],['brands','Brands'],['calendar','Calendar'],['approvals','Approvals'],['messages','Messages']];
  return `<div class="shell horizontal-shell">
    <header class="global-header">
      <a class="brand-lockup" href="#/home"><span class="logo-mark">w</span><span>WRM <b>Operations</b></span></a>
      <button class="icon-btn nav-toggle" data-action="toggle-menu" aria-label="Toggle navigation">Menu</button>
      <nav class="primary-nav" id="primary-nav">${nav.map(([key,label])=>`<a href="#/${key}" class="${active===key?'active':''}">${label}${key==='approvals'&&requestCount?`<b>${requestCount}</b>`:''}${key==='messages'&&unread?`<b>${unread}</b>`:''}</a>`).join('')}<div class="more-nav"><button class="nav-more" data-action="toggle-more">More</button><div id="more-menu"></div></div><div class="mobile-nav-tools"><div class="search-wrap"><input class="search" id="mobile-global-search" data-search-results="mobile-search-results" placeholder="Search work and people…" aria-label="Global search"><div id="mobile-search-results"></div></div><button class="icon-btn" aria-label="Updates" data-action="notifications">Updates</button></div></nav>
      <div class="header-tools"><div class="search-wrap"><input class="search" id="global-search" placeholder="Search…" aria-label="Global search"><div id="search-results"></div></div><button class="icon-btn" title="Notifications" aria-label="Notifications" data-action="notifications">Updates</button><button class="role-button" data-go="profile">${avatar(me,'sm')}<span class="who"><small>Profile</small>${esc(me.name)}</span></button></div>
    </header>
    <div class="dev-strip"><b>PRIVATE BETA</b><span>Signed in as ${esc(me.name)}</span><span class="local-status">Shared workspace</span></div><main class="main">${content}</main></div>`;
}

function pageHead(eyebrow,title,sub='',actions='') { return `<div class="page-head"><div><div class="eyebrow eyebrow-with-info"><span>${eyebrow}</span>${infoTip(sub,`About ${title}`)}</div><h1>${title}</h1></div><div>${actions}</div></div>`; }
function activityList(items,limit=10) { return items.length?`<div class="activity-list">${items.slice(0,limit).map(a=>`<div class="activity-item"><div class="activity-time">${fmtTime(a.created_at)}<br>${fmtDate(a.created_at)}</div><div class="activity-text">${personLink(user(a.user_id),a.project_id)} ${esc(a.message)}</div></div>`).join('')}</div>`:'<div class="empty">No activity yet.</div>'; }
function taskRow(t, head=false) {
  if(head) return `<div class="task-row table-head"><span>Task</span><span>Owner</span><span>Stage</span><span>Status</span><span>Deadline</span><span>Priority</span></div>`;
  const p=project(t.project_id), b=brand(p?.brand_id);
  return `<div class="task-row ${deptClass(t.department)}" data-go="task/${t.id}"><div class="task-title"><span class="dept-marker"></span>${esc(t.title)}<small>${esc(b?.name||'Brand')} · ${esc(p?.name||'Project')}</small></div><div class="task-owner" data-label="Owner">${personLink(user(t.owner_id),t.project_id,user(t.owner_id)?.name.split(' ')[0])}</div><span class="stage-tag" data-label="Stage">${esc(t.stage)}</span><div class="task-status" data-label="Status">${status(t.status)}</div><span class="deadline ${taskDueClass(t)}" data-label="Deadline">${fmtDateTime(t.deadline)}</span><div class="task-priority" data-label="Priority">${priority(t.priority)}</div></div>`;
}
function attentionRow(t){const p=project(t.project_id),b=brand(p?.brand_id);return `<article class="attention-row ${deptClass(t.department)}" data-go="task/${t.id}"><div class="attention-title"><span class="dept-marker"></span><span><b>${esc(t.title)}</b><small>${esc(b?.name||'Brand')} · ${esc(p?.name||'Project')}</small></span></div><div class="attention-meta">${status(t.status)}${priority(t.priority)}<span class="deadline ${taskDueClass(t)}">${fmtDateTime(t.deadline)}</span></div></article>`;}

function dashboard() {
  const ts=filteredTasks(state.tasks), dueToday=ts.filter(t=>taskDueClass(t)==='today'&&!['Complete'].includes(t.status)).length, overdue=ts.filter(t=>taskDueClass(t)==='overdue'&&!['Complete'].includes(t.status)).length, reviews=ts.filter(t=>t.status==='In Review'&&isReviewer(t)).length;
  const activeProjects=state.projects.filter(p=>p.status==='Active');
  const open=t=>!['Complete','Cancelled'].includes(t.status);
  const attention=ts.filter(t=>open(t)&&(['Needs Changes','Blocked'].includes(t.status)||taskDueClass(t)==='overdue')).slice(0,6);
  const needsN=ts.filter(t=>open(t)&&(taskDueClass(t)==='today'||['Needs Changes','Blocked'].includes(t.status)||(t.status==='In Review'&&isReviewer(t)))).length;
  const atRisk=ts.filter(t=>open(t)&&(taskDueClass(t)==='overdue'||t.status==='Blocked')).length;
  return shell(`<div class="page">
    ${pageHead('WRM / Operations','Your studio, today.',new Intl.DateTimeFormat('en-IN',{weekday:'long',day:'numeric',month:'long'}).format(new Date()),isManager()?'<button class="btn primary" data-action="new-project">+ New project</button>':'')}
    ${departmentFilters()}
    <section class="hero-board"><div class="hero-main"><div class="eyebrow">${S.heroEyebrow}</div><h1>${needsN} next action${needsN===1?'':'s'}.<br>${atRisk?`${atRisk} at risk.`:S.noRisk}</h1></div><div class="hero-side"><div class="hero-metric signal-yellow"><small>Needs action</small><strong>${needsN}</strong></div><div class="hero-metric signal-teal"><small>Awaiting review</small><strong>${reviews}</strong></div><div class="hero-metric signal-coral"><small>At risk</small><strong>${atRisk}</strong></div></div></section>
    <div class="grid dashboard-grid">
      <section class="panel"><div class="panel-head"><h2>Project progress</h2><a href="#/projects">View all</a></div><div class="panel-body grid cols-2">${activeProjects.slice(0,4).map(p=>{const b=brand(p.brand_id),pc=progress(p.id),pt=projectTasks(p.id),done=pt.filter(t=>['Complete'].includes(t.status)).length;return `<div class="project-card rating-card rating-${String(p.rating).replace('+','plus').toLowerCase()}" data-go="project/${p.id}"><div class="rating-line">${rating(p.rating,'Project rating')}<span class="brand-label"><span>${esc(b?.name||'Brand')}</span></span>${p.confidential?'<span class="confidential">CONFIDENTIAL</span>':''}</div><h3>${esc(p.name)}</h3><div class="progress"><span style="width:${pc}%"></span></div><div class="meta-line"><b>${pc}%</b><span>${done} / ${pt.length} Tasks complete</span></div></div>`}).join('')}</div></section>
      ${bandwidthView(ts)}
    </div>
    <div class="grid cols-2" style="margin-top:18px">
      <section class="panel attention-panel"><div class="panel-head"><h2>What needs attention</h2></div><div class="attention-list">${attention.map(attentionRow).join('')||'<div class="panel-body empty">'+S.attentionEmpty+'</div>'}</div></section>
      <section class="panel"><div class="panel-head"><h2>Recent activity</h2></div><div class="panel-body">${activityList(state.activity)}</div></section>
    </div>
  </div>`,'home');
}

function myWork() {
  const me=currentUser(), mine=state.tasks.filter(t=>t.owner_id===me.id), today=mine.filter(t=>new Date(t.deadline).toDateString()===new Date().toDateString()),doneToday=today.filter(t=>t.status==='Complete').length,dayTotal=today.length,dayLeft=Math.max(0,dayTotal-doneToday),dayPct=dayTotal?Math.round(doneToday/dayTotal*100):100;
  const hourStart=0,hourEnd=24,hours=Array.from({length:24},(_,i)=>hourStart+i), now=new Date(), nowPct=Math.max(0,Math.min(100,(now.getHours()+now.getMinutes()/60-hourStart)/(hourEnd-hourStart)*100));
  const claimed=new Set(),take=items=>items.filter(t=>!claimed.has(t.id)&&(claimed.add(t.id),true));
  const isOpen=t=>!['Complete','Cancelled'].includes(t.status),overdueMine=take(mine.filter(t=>isOpen(t)&&new Date(t.deadline)<now&&new Date(t.deadline).toDateString()!==now.toDateString()).sort((a,b)=>new Date(a.deadline)-new Date(b.deadline)));
  const groups=[['OVERDUE',overdueMine],['NEEDS CHANGES',take(mine.filter(t=>t.status==='Needs Changes'))],['NOW',take(mine.filter(t=>t.status==='In Progress'))],['TODAY',take(today.filter(t=>!['Complete'].includes(t.status)))],['IN REVIEW',take(mine.filter(t=>t.status==='In Review'))],['UPCOMING',take(mine.filter(t=>new Date(t.deadline)>new Date()&&taskDueClass(t)!=='today'&&!['Complete'].includes(t.status)).sort((a,b)=>new Date(a.deadline)-new Date(b.deadline)).slice(0,8))],['COMPLETED',take(mine.filter(t=>['Complete'].includes(t.status)).slice(0,5))]];
  return shell(`<div class="page">
    ${pageHead(`Good ${now.getHours()<12?'morning':now.getHours()<17?'afternoon':'evening'}, ${esc(me.name.split(' ')[0])}`,'My work',`${today.length} tasks today · ${mine.filter(t=>t.status==='Needs Changes').length} needs changes · ${mine.filter(t=>t.status==='In Review').length} in review`)}
    <section class="daily-progress"><div><div class="eyebrow">Today</div><h2>${doneToday} / ${dayTotal} Tasks cleared</h2></div><div class="progress daily-progress-track"><span style="width:${dayPct}%"></span></div><strong>${!dayTotal?'No tasks due':dayLeft?`${dayLeft} left`:S.dayClear}</strong></section>
    ${doneToday?`<div class="completion-burst">${S.doneToday(doneToday)}</div>`:''}
    <section class="timeline" tabindex="0" aria-label="24-hour work strip. Scroll horizontally for later hours."><div class="timeline-head"><div><div class="eyebrow" style="color:#aaa">Today</div><h2 style="margin:2px 0">24-hour work strip</h2></div><strong>${today.length?`${doneToday}/${today.length} cleared`:'No deadlines today'}</strong></div><div class="horizontal-cue" aria-hidden="true">Scroll horizontally for later hours →</div><div class="timeline-hours">${hours.map(h=>`<div class="hour">${String(h).padStart(2,'0')}</div>`).join('')}<i class="now-line" style="left:${nowPct}%"></i>${hours.map(h=>{const due=today.filter(t=>new Date(t.deadline).getHours()===h);return due.length?`<button class="time-task" data-deadline-hour="${h}" title="${esc(due.map(t=>`${fmtTime(t.deadline)} · ${t.title}`).join(' / '))}" aria-label="${h}:00 · ${due.length} task${due.length===1?'':'s'} due" style="left:${h/24*100}%;top:46px"><b>${String(h).padStart(2,'0')}</b><br>${due.length} task${due.length===1?'':'s'}</button>`:''}).join('')}</div></section>
    ${groups.filter(([,items])=>items.length).map(([label,items])=>`<div class="section-label">${label} <b>${items.length}</b></div><div class="panel">${items.map(t=>taskRow(t)).join('')}</div>`).join('') || '<div class="empty"><h2>'+S.workEmptyTitle+'</h2><p>'+S.workEmptyBody+'</p></div>'}
  </div>`,'my-work');
}

function projectsView() {
  const visibleProjects=departmentFilter==='All'?state.projects:state.projects.filter(p=>(!projectTasks(p.id).length||projectTasks(p.id).some(t=>t.department===departmentFilter)));
  return shell(`<div class="page">${pageHead(S.eyProjects,'Projects',`${visibleProjects.filter(p=>p.status==='Active').length} active in your scope`,isManager()?'<button class="btn primary" data-action="new-project">+ New project</button>':'')}
    ${departmentFilters()}
    ${['Active','On Hold','Draft','Completed'].map(group=>{const ps=visibleProjects.filter(p=>p.status===group);if(!ps.length)return'';return `<div class="section-label">${group} <b>${ps.length}</b></div><div class="grid cols-3">${ps.map(p=>{const b=brand(p.brand_id),pc=progress(p.id);return `<article class="project-card rating-card rating-${String(p.rating).replace('+','plus').toLowerCase()} ${group==='On Hold'?'on-hold':''}" data-go="project/${p.id}"><div class="rating-line">${rating(p.rating,'Project rating')}${status(p.status)}${p.confidential?'<span class="confidential">CONFIDENTIAL</span>':''}</div><div class="brand-name">${esc(b?.name||'Brand')} · ${esc(p.type)}</div><h3>${esc(p.name)}</h3><div class="progress"><span style="width:${pc}%"></span></div><div class="meta-line"><b>${pc}% complete</b><span>Internal ${fmtDate(p.internal_deadline)}</span></div><div class="meta-line" style="margin-top:9px"><span>${projectTasks(p.id).length} visible tasks</span><span>Client ${fmtDate(p.client_deadline)}</span></div></article>`}).join('')}</div>`}).join('')||'<div class="empty">No projects in this Department scope.</div>'}
  </div>`,'projects');
}

function projectTeam(p,ts) {
  const ids=new Set([...projectPeopleIds(p),...ts.flatMap(t=>[t.owner_id,t.reviewer_id,...t.contributors])].filter(Boolean));
  const people=[...ids].map(user).filter(Boolean);
  const grouped=Object.groupBy?Object.groupBy(people,u=>u.department):people.reduce((a,u)=>((a[u.department]??=[]).push(u),a),{});
  return Object.entries(grouped).sort(([a],[b])=>a.localeCompare(b)).map(([dept,members])=>`<section class="team-group ${deptClass(dept)}"><div class="team-group-head">${esc(dept)} · ${members.length}</div>${alphaPeople(members).map(u=>{const owned=ts.filter(t=>t.owner_id===u.id);const reviewed=ts.filter(t=>t.reviewer_id===u.id);const role=reviewed.length?'Reviewer / project lead':'Project member';return `<div class="team-member"><div class="team-person">${personLink(u,p.id)}<small>${esc(u.title)} · ${esc(u.department)}</small>${isManager()?presence(u):''}</div><span class="stage-tag">${esc(owned.length?`${owned.length} task${owned.length>1?'s':''}`:role)}</span></div>`}).join('')}</section>`).join('');
}

function projectView(id) {
  const p=project(id); if(!p) return notFound(); const b=brand(p.brand_id),ts=projectTasks(p.id),pc=progress(p.id), counts=['Complete','In Progress','In Review','Needs Changes','Blocked'].map(s=>[s,ts.filter(t=>t.status===s).length]);
  const tabs=['overview','tasks','board','brief','people','activity'];
  let body='';
  if(projectTab==='overview') body=`<div class="grid cols-4">${counts.map(([s,n],i)=>`<div class="stat" style="--tone:${['#35c98a','#15adc2','#102a45','#ef4754','#650d27'][i]}"><div class="stat-num">${n}</div><div class="stat-label">${s}</div></div>`).join('')}</div><div class="grid cols-2" style="margin-top:18px"><section class="panel"><div class="panel-head"><h2>Today + upcoming</h2></div>${ts.slice().sort((a,b)=>new Date(a.deadline)-new Date(b.deadline)).slice(0,7).map(t=>taskRow(t)).join('')}</section><section class="panel"><div class="panel-head"><h2>Project people</h2><button class="btn ghost" data-project-tab="people">View people</button></div><div class="panel-body">${alphaPeople([...new Set([...projectPeopleIds(p),...ts.map(t=>t.owner_id)])].map(user).filter(Boolean)).slice(0,8).map(u=>personLink(u,p.id)).join('<br><br>')}</div></section></div>`;
  if(projectTab==='tasks') body=`<div style="display:flex;justify-content:space-between;margin-bottom:12px"><div class="eyebrow">${ts.length} accountable tasks</div><button class="btn acid" data-action="new-task">+ New task</button></div><div class="panel compact-table">${taskRow(null,true)}${ts.map(t=>taskRow(t)).join('')}</div>`;
  if(projectTab==='board') { const stages=p.workflow.length?p.workflow:['Strategy','Copy','Design','Internal Review','CS Review','Final']; body=`<div class="horizontal-cue" aria-hidden="true">Scroll horizontally to see every workflow stage →</div><div class="board" tabindex="0" aria-label="Workflow board. Scroll horizontally for more stages.">${stages.map((s,i)=>{const cards=ts.filter(t=>t.status==='Complete'?s==='Final':t.stage===s);return `<div class="board-col"><div class="board-head" style="--accent:${['#23B4C6','#F5C34E','#E74D61','#0D1D33','#23B4C6','#F5C34E'][i%6]}"><span>${esc(s)}</span><b>${cards.length}</b></div>${cards.map(t=>`<article class="board-card ${deptClass(t.department)}" data-go="task/${t.id}"><h3><span class="dept-marker"></span>${esc(t.title)}</h3>${status(t.status)}<div class="board-card-foot">${personLink(user(t.owner_id),p.id,'')}<span class="deadline ${taskDueClass(t)}">${fmtDate(t.deadline)}</span></div>${isManager()?`<select class="move-select" data-move-task="${t.id}" aria-label="Move task"><option value="">MOVE →</option>${stages.filter(x=>x!==t.stage).map(x=>`<option>${esc(x)}</option>`).join('')}</select>`:''}</article>`).join('')||'<div class="kanban-empty">No work here</div>'}</div>`}).join('')}</div>`; }
  if(projectTab==='brief') { const labels={background:'Background',objective:'Objective',mandate:'Mandate',clientAsk:'What the client asked for',outputs:'Expected outputs',mandatory:'Mandatory requirements',references:'References',resources:'Client-supplied resources',notes:'Notes'}; body=`<div class="split"><div>${Object.entries(labels).map(([k,l])=>`<section class="panel" style="margin-bottom:12px"><div class="panel-head"><h2>${l}</h2></div><div class="panel-body"><p>${esc(p.brief[k]||'Not added yet.')}</p></div></section>`).join('')}</div><aside class="panel"><div class="panel-head"><h2>Useful links + files</h2></div><div class="panel-body"><div class="reference-chips">${p.resources.map(r=>`<span class="chip">${esc(r)}</span>`).join('')}</div></div></aside></div>`; }
  if(projectTab==='people') body=`<div class="page-head"><div><div class="eyebrow">People working here</div><h2>Project people · ${new Set([...projectPeopleIds(p),...ts.flatMap(t=>[t.owner_id,t.reviewer_id])]).size}</h2></div></div><div class="grid cols-2">${projectTeam(p,ts)}</div>`;
  if(projectTab==='activity') body=`<section class="panel"><div class="panel-head"><h2>Project activity</h2></div><div class="panel-body">${activityList(activityFor('project_id',p.id),Infinity)}</div></section>`;
  return shell(`<div class="page"><section class="project-banner project-rating-${String(p.rating).replace('+','plus').toLowerCase()}"><div class="project-identity"><div class="eyebrow project-context" style="color:#b8d7df"><span>${esc(b.name)}</span><span aria-hidden="true">·</span><span>${esc(p.type)}</span></div><h1>${esc(p.name)}</h1><div class="project-state-line"><div class="project-flags"><span class="rating-context"><small>Project rating</small>${rating(p.rating,'Project rating')}</span> ${status(p.status)} ${p.confidential?'<span class="confidential">CONFIDENTIAL</span>':''}</div>${isManager()?`<div class="project-actions"><button class="btn ghost light" data-edit-project="${p.id}">Edit Project</button><button class="btn ghost light" data-membership="projects" data-id="${p.id}">Manage people</button>${currentUser().role==='SUPER ADMIN'?`<button class="btn danger" data-beta-remove="projects" data-id="${p.id}">Remove Project</button>`:''}</div>`:''}</div></div><div class="project-dates"><div class="date-box"><small>Internal handoff</small><strong>${fmtDate(p.internal_deadline)}</strong></div><div class="date-box"><small>Client delivery</small><strong>${fmtDate(p.client_deadline)}</strong></div><div class="date-box"><small>Delivery buffer</small><strong>${deadlineBuffer(p)}d</strong></div><div class="date-box"><small>Complete</small><strong>${pc}%</strong></div></div></section><div class="tabs">${tabs.map(tab=>`<button class="tab ${projectTab===tab?'active':''}" data-project-tab="${tab}">${tab}</button>`).join('')}</div>${body}</div>`,'projects');
}

function taskView(id) {
  const t=task(id); if(!t)return notFound(); const p=project(t.project_id),b=brand(p.brand_id),owner=user(t.owner_id),reviewer=user(t.reviewer_id),latest=t.versions[0],openDeps=(t.dependencies||[]).filter(id=>{const d=task(id);return d&&d.status!=='Complete'});
  let actions='';
  if(t.owner_id===state.currentUserId) {
    if(t.status==='Blocked'&&openDeps.length) actions+=`<button class="btn" disabled title="Finish the blocking task first">Waiting on dependency</button>`;
    else if(['To Do','Blocked','On Hold'].includes(t.status)||(t.status==='In Review'&&!latest)) actions+=`<button class="btn acid" data-task-action="start" data-task="${t.id}">Start work</button>`;
    if(t.status==='Needs Changes') actions+=`<button class="btn coral" data-task-action="revise" data-task="${t.id}">Start revision</button>`;
    if(t.status==='In Progress') actions+=`<button class="btn primary" data-action="submit-work" data-task="${t.id}">Submit work</button>`;
  }
  if(t.status==='In Review'&&latest&&isReviewer(t)) actions+=`<button class="btn acid" data-review="approve" data-task="${t.id}">Approve</button><button class="btn coral" data-review="needs-changes" data-task="${t.id}">${S.sendBack}</button>`;
  if(t.status==='Approved'&&(t.owner_id===state.currentUserId||isManager())) actions+=`<button class="btn acid" data-task-action="complete" data-task="${t.id}">Mark complete</button>`;
  if(isManager()) actions+=`<button class="btn ghost" data-action="edit-task" data-task="${t.id}">Edit task</button>`;
  if(currentUser().role==='SUPER ADMIN')actions+=`<button class="btn danger" data-beta-remove="tasks" data-id="${t.id}">Remove Task</button>`;
  const cloud=[['Brand Book',b.brand_book_url||b.brand_book_file],['Website',b.website],['Instagram',b.instagram],['YouTube',b.youtube],['LinkedIn',b.linkedin]].map(([label,url])=>[label,safeHref(url)]).filter(([,url])=>url);
  return shell(`<div class="page"><div class="task-shell">
    <header class="task-header project-rating-${String(p.rating).replace('+','plus').toLowerCase()}"><div><div class="eyebrow">${brandLabel(b)} / ${esc(p.name)}</div><h1>${esc(t.title)}</h1><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">${status(t.status)} ${priority(t.priority)} <strong class="deadline ${taskDueClass(t)}">Due ${fmtDateTime(t.deadline)}${t.status==='Complete'?'':` · ${relative(t.deadline)}`}</strong></div></div><div class="task-actions">${actions}</div>${t.status==='Complete'?'<div class="task-milestone">Done. Nothing left on this one.</div>':t.status==='Approved'?`<div class="task-milestone">Approved at ${esc(t.stage)}. Ready to close out.</div>`:''}</header>${approvalJourney(t)}
    <div>
      <section class="panel"><div class="panel-head"><h2>Brief</h2></div><div class="panel-body"><p class="brief">${esc(t.brief)}</p><div class="section-label">References</div><div class="reference-chips">${t.references.map(r=>[r,safeHref(r.url)]).filter(([,url])=>url).map(([r,url])=>`<a class="chip" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(r.label)}</a>`).join('')}${safeHref(b.brand_book_url||b.brand_book_file)?`<a class="chip" href="${esc(safeHref(b.brand_book_url||b.brand_book_file))}" target="_blank" rel="noopener noreferrer">Brand Book</a>`:''}</div>${t.dependencies.length?`<div class="notice dependency-notice" style="margin-top:15px"><b>${S.depLabel}</b><br>${t.dependencies.map(id=>esc(task(id)?.title||`Task ${id}`)).join(', ')}<small>${S.depNote}</small></div>`:''}</div></section>
      <section class="panel" style="margin-top:16px"><div class="panel-head"><h2>Comments</h2><span>${t.comments.length}</span></div><div class="panel-body"><div class="comments">${t.comments.map(c=>`<div class="comment">${avatar(user(c.user_id),'sm')}<div class="comment-bubble">${personLink(user(c.user_id),p.id)}<p>${esc(c.body)}</p><small>${fmtDateTime(c.created_at)}</small></div></div>`).join('')||'<div class="empty">'+S.noComments+'</div>'}</div><form class="comment-form" data-task="${t.id}"><label class="sr-only" for="task-comment-${t.id}">Write a comment</label><input class="input" id="task-comment-${t.id}" name="body" placeholder="Write a comment…" required><button class="btn primary">Add</button></form></div></section>
      <section style="margin-top:18px"><div class="section-label">Versions + decision history</div>${t.versions.length?t.versions.map(v=>`<article class="version"><div class="version-head"><b>V${v.number}</b>${status(v.status)}</div><div class="version-body"><div class="meta-line"><span>Submitted by ${esc(userName(v.submitter_id))}</span><span>${fmtDateTime(v.submitted_at)}</span></div>${v.note?`<p style="margin-top:10px">${esc(v.note)}</p>`:''}<div class="reference-chips">${safeHref(v.link)?`<a class="chip" href="${esc(safeHref(v.link))}" target="_blank" rel="noopener noreferrer">Open link</a>`:''}</div>${v.feedback?`<div class="feedback"><div class="eyebrow">Decision · ${esc(userName(v.reviewer_id))} · ${fmtDateTime(v.reviewed_at||v.submitted_at)}</div><p>${esc(v.feedback)}</p></div>`:''}</div></article>`).join(''):'<div class="empty">'+S.noVersions+'</div>'}</section>
      <section style="margin-top:18px"><div class="section-label">Activity</div><div class="panel"><div class="panel-body">${activityList(activityFor('task_id',t.id),Infinity)}</div></div></section>
    </div>
    <aside>
      <section class="panel"><div class="panel-head"><h2>People + timing</h2></div><div class="panel-body side-facts"><div class="fact"><small>Owner</small><strong>${personLink(owner,p.id)}</strong></div><div class="fact"><small>Reviewer</small><strong>${personLink(reviewer,p.id)}</strong></div><div class="fact"><small>Stage</small><strong>${esc(t.stage)}</strong></div><div class="fact"><small>Department</small><strong><span class="dept-marker ${deptClass(t.department)}"></span>${esc(t.department)}</strong></div><div class="fact"><small>Task deadline</small><strong class="deadline ${taskDueClass(t)}">${fmtDateTime(t.deadline)}</strong></div><div class="fact"><small>Project deadline</small><strong>${fmtDateTime(p.internal_deadline)}</strong></div></div></section>
      <section class="panel brand-cloud"><div class="panel-head"><h2>${brandLabel(b)} · Brand Hub</h2></div><div class="panel-body"><p>${esc(b.notes)}</p><div class="cloud">${cloud.map(([l,u])=>`<a class="chip" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(l)}</a>`).join('')}</div><button class="btn ghost" style="margin-top:12px" data-go="brand/${b.id}">Open brand</button></div></section>
    </aside>
  </div></div>`,'my-work');
}

function approvals() {
  const waiting=state.tasks.filter(t=>t.status==='In Review'&&isReviewer(t));
  const requests=state.profileRequests.filter(r=>r.status==='Pending'&&r.approver_id===state.currentUserId);
  return shell(`<div class="page">${pageHead(S.eyApprovals,'Approvals',`${waiting.length} work review${waiting.length===1?'':'s'} · ${requests.length} profile request${requests.length===1?'':'s'}`)}
  <div class="section-label">Work reviews · ${waiting.length}</div>${waiting.length?`<div class="grid cols-2">${waiting.map(t=>{const p=project(t.project_id),b=brand(p.brand_id),v=t.versions[0];return `<article class="panel rating-card rating-${String(p.rating).replace('+','plus').toLowerCase()}"><div class="panel-head"><h2>${brandLabel(b)} · ${esc(p?.name||'Project')}</h2>${status(t.status)}</div><div class="panel-body"><h3>${esc(t.title)}</h3><div class="meta-line"><span>Owner: ${personLink(user(t.owner_id),p?.id)}</span><span>Version V${v?.number||'—'}</span></div><div class="meta-line" style="margin-top:8px"><span>Submitted ${v?fmtDateTime(v.submitted_at):'—'}</span><b class="deadline ${taskDueClass(t)}">Due ${fmtDateTime(t.deadline)}</b></div><div class="task-actions" style="justify-content:flex-start;margin-top:15px"><button class="btn primary" data-go="task/${t.id}">Open review</button>${v?`<button class="btn acid" data-review="approve" data-task="${t.id}">Approve</button><button class="btn coral" data-review="needs-changes" data-task="${t.id}">${S.sendBack}</button>`:''}</div></div></article>`}).join('')}</div>`:'<div class="empty">'+S.noReviews+'</div>'}
  <div class="section-label">Profile requests · ${requests.length}</div>${requests.length?`<div class="grid cols-2">${requests.map(r=>{const who=user(r.user_id);return `<article class="request-card"><div><div class="eyebrow">${esc(r.field.replaceAll('_',' '))}</div><h3>${personLink(who)}</h3><p><s>${esc(r.old_value||'Not set')}</s><br><b>${esc(skillText(r.new_value))}</b></p><small>Requested ${fmtDateTime(r.created_at)}</small></div><div class="task-actions"><button class="btn acid" data-profile-request="${r.id}" data-decision="approve">Approve</button><button class="btn ghost" data-profile-request="${r.id}" data-decision="reject">Reject</button></div></article>`}).join('')}</div>`:'<div class="empty">'+S.noRequests+'</div>'}</div>`,'approvals');
}

function brandsView() {
  return shell(`<div class="page">${pageHead(S.eyBrands,'Brands',S.brandsSub,isManager()?'<button class="btn primary" data-action="new-brand">+ New brand</button>':'')}<div class="grid cols-3">${state.brands.map(b=>{const ps=state.projects.filter(p=>p.brand_id===b.id&&p.status==='Active'),ts=ps.flatMap(p=>projectTasks(p.id));return `<article class="brand-card rating-card rating-${String(b.rating||'B').replace('+','plus').toLowerCase()}" data-go="brand/${b.id}"><div class="rating-line">${rating(b.rating,'Brand rating')}<span class="stage-tag">${esc(b.status)}</span></div><h3>${esc(b.name)}</h3><p>${esc(b.notes)}</p><div class="meta-line"><b>${ps.length} active projects</b><span>${activeTasks(ts).length} active tasks</span></div></article>`}).join('')}</div></div>`,'brands');
}

function brandView(id) {
  const b=brand(id);if(!b)return notFound(); const ps=state.projects.filter(p=>p.brand_id===b.id&&p.status==='Active'), acts=activityFor('brand_id',b.id); const links=[['Brand Book',b.brand_book_url||b.brand_book_file],['Website',b.website],['Instagram',b.instagram],['YouTube',b.youtube],['LinkedIn',b.linkedin],['Facebook',b.facebook],['X / Twitter',b.twitter]].map(([label,url])=>[label,safeHref(url)]).filter(([,url])=>url);
  return shell(`<div class="page"><section class="brand-hero rating-card rating-${String(b.rating||'B').replace('+','plus').toLowerCase()}"><div class="brand-info"><div class="brand-hero-actions">${isManager()?`<button class="btn ghost" data-edit-brand="${b.id}">Edit Brand</button><button class="btn ghost" data-membership="brands" data-id="${b.id}">Manage people</button>${currentUser().role==='SUPER ADMIN'?`<button class="btn danger" data-beta-remove="brands" data-id="${b.id}">Remove Brand</button>`:''}`:''}</div><div class="eyebrow">Brand repository · ${esc(b.status)}</div><div class="rating-line">${rating(b.rating,'Brand rating')}<h1>${esc(b.name)}</h1></div><p>${esc(b.notes)}</p><div class="cloud">${links.map(([l,u])=>`<a class="chip" href="${esc(u)}" target="_blank">${esc(l)}</a>`).join('')}</div></div></section><div class="grid cols-2"><section>${brandPeoplePanel(b)}<div class="section-label">Active projects</div><div class="grid">${ps.map(p=>{const pc=progress(p.id);return `<div class="project-card rating-card rating-${String(p.rating).replace('+','plus').toLowerCase()}" data-go="project/${p.id}"><div class="rating-line">${rating(p.rating,'Project rating')}${status(p.status)}</div><h3>${esc(p.name)}</h3><div class="progress"><span style="width:${pc}%"></span></div><div class="meta-line"><b>${pc}% complete</b><span>${projectTasks(p.id).length} tasks</span></div></div>`}).join('')}</div></section><section><div class="contact-section-head"><div class="section-label">${S.clientTeam} · ${b.contacts.length}</div><button class="btn acid" data-add-contact="${b.id}">+ Add person</button></div><div class="contact-grid">${b.contacts.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(c=>`<article class="contact-card"><div class="contact-card-head"><div><h3>${esc(c.name)}</h3><div class="designation">${esc(c.designation||'Title not added')}${c.context?` · ${esc(c.context)}`:''}</div></div><div class="contact-actions"><button class="btn ghost" data-edit-contact="${c.id}" data-brand="${b.id}">Edit</button><button class="btn danger" data-remove-contact="${c.id}" data-brand="${b.id}">Remove</button></div></div>${c.notes?`<p>${esc(c.notes)}</p>`:''}<div class="contact-details">${c.email?`<a href="mailto:${esc(c.email)}">${esc(c.email)}</a>`:''}${c.phone?`<a href="tel:${esc(c.phone)}">${esc(c.phone)}</a>`:''}</div></article>`).join('')||'<div class="empty">No client-side people added yet.</div>'}</div><div class="section-label">Recent activity</div><div class="panel"><div class="panel-body">${activityList(acts)}</div></div></section></div></div>`,'brands');
}

function people() {
  return shell(`<div class="page">${pageHead('People','People in your scope',`${state.users.length} colleagues connected through reporting lines, Departments and Projects`)}<div class="people-grid">${alphaPeople(state.users).map(u=>{const work=activeTasks(state.tasks.filter(t=>t.owner_id===u.id)),today=work.filter(t=>taskDueClass(t)==='today').length;return `<article class="people-card ${deptClass(u.department)}">${avatar(u)}<div class="people-main"><button class="person-link people-name-link" data-person="${u.id}"><span>${esc(u.name)}</span></button><small>${esc(u.title)} · ${esc(u.department)}</small>${isManager()||u.id===state.currentUserId?`<div>${presence(u)} <span class="presence-time">${u.is_online?'Active in this session':'Not active in this session'}</span></div>`:''}</div><div class="people-work"><b>${work.length}</b> active<br><b>${today}</b> due today</div><div class="people-actions"><button class="btn ghost" data-person="${u.id}">View profile</button>${u.id!==state.currentUserId?`<button class="btn acid" data-message-person="${u.id}">Message</button>`:''}</div></article>`}).join('')}</div></div>`,'people');
}

function profileView() {
  const me=currentUser(), manager=user(me.manager_id), mine=state.tasks.filter(t=>t.owner_id===me.id), pending=state.profileRequests.filter(r=>r.user_id===me.id&&r.status==='Pending');
  const pendingFor=field=>pending.find(r=>r.field===field);
  const value=(field,current,formatter=v=>v)=>{const r=pendingFor(field);return `${esc(formatter(current)||'—')}${r?`<div class="pending-value"><b>${esc(formatter(r.new_value))}</b><br>Pending approval from ${esc(userName(r.approver_id))}</div>`:''}`};
  const skills=Array.isArray(me.skills)?me.skills:[];
  return shell(`<div class="page"><section class="profile-hero" style="--person:${safeColor(me.color)}"><div class="profile-avatar">${esc(me.initials)}</div><div><div class="eyebrow" style="color:#b8d7df">My profile</div><h1>${esc(me.name)}</h1><p style="margin:0;color:#d9e7eb">${esc(me.title)} · ${esc(me.department)} Department</p><div class="profile-presence">${presence(me)} · ${me.is_online?`Logged in ${fmtDateTime(me.last_login)}`:`Last active ${me.last_logout?fmtDateTime(me.last_logout):'not recorded'}`}</div></div><div class="profile-actions"><button class="btn acid" data-action="edit-profile">Edit / request change</button><button class="btn ghost light" data-action="logout">Log out</button></div></section>
    <div class="grid cols-4" style="margin-top:16px"><div class="stat" style="--tone:var(--cyan)"><div class="stat-num">${activeTasks(mine).length}</div><div class="stat-label">Active tasks</div></div><div class="stat" style="--tone:var(--amber)"><div class="stat-num">${mine.filter(t=>taskDueClass(t)==='today').length}</div><div class="stat-label">Due today</div></div><div class="stat" style="--tone:var(--navy)"><div class="stat-num">${mine.filter(t=>t.status==='In Review').length}</div><div class="stat-label">In review</div></div><div class="stat" style="--tone:var(--coral)"><div class="stat-num">${pending.length}</div><div class="stat-label">Pending changes</div></div></div>
    <div class="profile-grid"><section class="panel"><div class="panel-head"><h2>Contact</h2></div><div class="panel-body"><dl class="profile-list"><dt>Work email</dt><dd><a href="mailto:${esc(me.email)}">${esc(me.email)}</a></dd><dt>Phone</dt><dd>${value('phone',me.phone)}</dd><dt>Location</dt><dd>${value('location',me.location)}</dd></dl></div></section><section class="panel"><div class="panel-head"><h2>Work</h2></div><div class="panel-body"><dl class="profile-list"><dt>Department</dt><dd>${value('department',me.department)}</dd><dt>Designation</dt><dd>${value('title',me.title)}</dd><dt>Seniority</dt><dd>${value('seniority',me.seniority)}</dd><dt>Reports to</dt><dd>${manager?personLink(manager):'—'}</dd><dt>Joined</dt><dd>${fmtDate(me.joined_at,{year:'numeric'})}</dd><dt>Last login</dt><dd>${me.last_login?fmtDateTime(me.last_login):'Not recorded'}</dd><dt>Current session</dt><dd>${me.is_online?'Active':'Signed out'}</dd></dl></div></section><section class="panel"><div class="panel-head"><h2>About</h2></div><div class="panel-body"><p>${value('bio',me.bio)}</p><div class="section-label">Skills</div><div class="cloud">${skills.map(s=>`<span class="chip">${esc(s)}</span>`).join('')}</div>${pendingFor('skills')?`<div class="pending-value">${esc(skillText(pendingFor('skills').new_value))}<br>Pending approval</div>`:''}</div></section><section class="panel current-work-panel"><div class="panel-head"><h2>Current work</h2></div><div class="profile-work-list">${mine.slice(0,6).map(t=>{const p=project(t.project_id),b=brand(p.brand_id);return `<article class="profile-task" data-go="task/${t.id}"><div class="profile-task-title"><b>${esc(t.title)}</b><small>${esc(b.name)} · ${esc(p.name)}</small></div><div class="profile-task-meta">${status(t.status)}<span class="deadline ${taskDueClass(t)}">${fmtDateTime(t.deadline)}</span>${priority(t.priority)}</div></article>`}).join('')||'<div class="panel-body empty">No active assignments.</div>'}</div></section></div>
    <div class="section-label">Profile change history</div>${state.profileRequests.filter(r=>r.user_id===me.id).length?`<div class="grid cols-2">${state.profileRequests.filter(r=>r.user_id===me.id).map(r=>`<div class="request-card"><div><b>${esc(r.field.replaceAll('_',' '))}</b><p>${esc(r.old_value||'Not set')} → ${esc(skillText(r.new_value))}</p><small>${fmtDateTime(r.created_at)}</small></div><span class="stage-tag">${r.status==='Pending'?'Pending approval':esc(r.status)}</span></div>`).join('')}</div>`:'<div class="empty">No profile changes requested.</div>'}
  </div>`,'profile');
}

function calendarEvents(){
  const events=[];
  state.tasks.forEach(t=>{const p=project(t.project_id),b=brand(p?.brand_id);events.push({date:t.deadline,type:'Task',title:t.title,context:b?.name||'',go:`task/${t.id}`,department:t.department})});
  state.projects.forEach(p=>{const b=brand(p.brand_id),dept=[...new Set(projectTasks(p.id).map(t=>t.department))].join(', ');if(p.start_date)events.push({date:p.start_date,type:'Campaign start',title:p.name,context:b?.name||'',go:`project/${p.id}`,department:dept});if(p.end_date)events.push({date:p.end_date,type:'Campaign end',title:p.name,context:b?.name||'',go:`project/${p.id}`,department:dept});if(p.internal_deadline)events.push({date:p.internal_deadline,type:'Project internal',title:p.name,context:b?.name||'',go:`project/${p.id}`,department:dept});if(p.client_deadline)events.push({date:p.client_deadline,type:'Client deadline',title:p.name,context:b?.name||'',go:`project/${p.id}`,department:dept})});
  return events.filter(e=>calendarDepartment==='All'||String(e.department).split(', ').includes(calendarDepartment)).sort((a,b)=>parseDay(a.date)-parseDay(b.date));
}
const calendarTime=e=>/^\d{4}-\d{2}-\d{2}$/.test(e.date)?'All day':fmtTime(e.date);
function calendarEvent(e){const full=`${S.eventLabel[e.type]||e.type}: ${e.title}. ${calendarTime(e)} · ${e.context}`;return `<button class="calendar-event event-${e.type.toLowerCase().replaceAll(' ','-')}" data-go="${e.go}" title="${esc(full)}" aria-label="${esc(full)}"><small>${esc(S.eventLabel[e.type]||e.type)}</small><b>${esc(e.title)}</b><span>${calendarTime(e)} · ${esc(e.context)}</span></button>`;}
function calendarViewPage(){
  const events=calendarEvents(),now=new Date(),selected=new Date(calendarDate),year=selected.getFullYear(),month=selected.getMonth(),monthStart=new Date(year,month,1),gridStart=new Date(year,month,1-monthStart.getDay());
  const calendarHeading=calendarView==='month'?new Intl.DateTimeFormat('en-IN',{month:'long',year:'numeric'}).format(selected):calendarView==='week'?`Week of ${fmtDate(new Date(year,month,selected.getDate()-selected.getDay()))}`:calendarView==='day'?new Intl.DateTimeFormat('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(selected):`Agenda from ${fmtDate(selected)}`;
  const controls=`<div class="calendar-tools"><div class="date-nav"><button data-calendar-move="-1" aria-label="Previous day" title="Previous day">←</button><button data-calendar-today>Today</button><button data-calendar-move="1" aria-label="Next day" title="Next day">→</button><input type="date" data-calendar-date value="${localDateInput(selected).slice(0,10)}" aria-label="Choose date"></div><div class="view-switch">${['month','week','day','agenda'].map(v=>`<button class="${calendarView===v?'active':''}" data-calendar-view="${v}">${v}</button>`).join('')}</div><label>Department <select data-calendar-dept>${options(['All',...(['LEADERSHIP','SUPER ADMIN'].includes(currentUser().role)?[...new Set(state.users.map(u=>u.department))]:state.scopeDepartments||[])],calendarDepartment)}</select></label></div>`;
  let body='';
  if(calendarView==='month') body=`<div class="calendar-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<b>${d}</b>`).join('')}</div><div class="month-grid">${Array.from({length:42},(_,i)=>{const d=new Date(gridStart);d.setDate(d.getDate()+i);const key=d.toDateString(),dayEvents=events.filter(e=>parseDay(e.date).toDateString()===key);return `<section class="calendar-day ${d.getMonth()!==month?'muted':''} ${key===now.toDateString()?'today':''} ${key===selected.toDateString()?'selected':''}"><strong>${d.getDate()}</strong>${dayEvents.slice(0,4).map(calendarEvent).join('')}${dayEvents.length>4?`<small>+${dayEvents.length-4} more</small>`:''}</section>`}).join('')}</div>`;
  if(calendarView==='week'){const start=new Date(selected);start.setDate(selected.getDate()-selected.getDay());body=`<div class="horizontal-cue" aria-hidden="true">Scroll horizontally to see all seven days →</div><div class="week-grid" tabindex="0" aria-label="Week calendar. Scroll horizontally for every day.">${Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);const es=events.filter(e=>parseDay(e.date).toDateString()===d.toDateString());return `<section class="week-day"><header><b>${new Intl.DateTimeFormat('en-IN',{weekday:'short'}).format(d)}</b><strong>${d.getDate()}</strong></header>${es.map(calendarEvent).join('')||'<small>No deadlines</small>'}</section>`}).join('')}</div>`}
  if(calendarView==='day') body=`<div class="day-agenda"><h2>${new Intl.DateTimeFormat('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(selected)}</h2>${events.filter(e=>parseDay(e.date).toDateString()===selected.toDateString()).map(calendarEvent).join('')||'<div class="empty">No deadlines on this date.</div>'}</div>`;
  if(calendarView==='agenda'){const cutoff=new Date(selected);cutoff.setHours(0,0,0,0);body=`<div class="agenda-list">${events.filter(e=>parseDay(e.date)>=cutoff).slice(0,40).map(e=>`<div class="agenda-row"><time>${fmtDate(e.date)}<br>${calendarTime(e)}</time>${calendarEvent(e)}</div>`).join('')||'<div class="empty">No upcoming milestones from this date.</div>'}</div>`;}
  return shell(`<div class="page">${pageHead(S.eyCalendar,calendarHeading,S.calendarSub)}${controls}${body}</div>`,'calendar');
}

function messageThreads(){
  const grouped=new Map();state.messages.forEach(m=>{const partner=m.sender_id===state.currentUserId?m.recipient_id:m.sender_id,key=`${partner}:${Number(m.project_id||0)}`;if(!grouped.has(key))grouped.set(key,{partnerId:partner,projectId:Number(m.project_id||0),items:[]});grouped.get(key).items.push(m)});
  return [...grouped.values()].map(t=>({...t,latest:t.items.at(-1),unread:t.items.filter(m=>m.recipient_id===state.currentUserId&&!m.read_at).length})).filter(t=>user(t.partnerId)).sort((a,b)=>new Date(b.latest.created_at)-new Date(a.latest.created_at));
}
async function markVisibleThreadRead(){
  const [name,personId,projectId]=route();if(name!=='messages')return;
  const threads=messageThreads(),selected=personId?threads.find(t=>t.partnerId===Number(personId)&&t.projectId===Number(projectId||0)):threads[0];
  if(!selected?.unread)return;const key=`${selected.partnerId}:${selected.projectId}`;if(readingThreadKey===key)return;readingThreadKey=key;
  try{await api('/api/messages/read',{method:'POST',body:JSON.stringify({partnerId:selected.partnerId,projectId:selected.projectId})});await refresh(false);render();}catch{}finally{readingThreadKey='';}
}

function messagesView(personId=null,projectId=null){
  const threads=messageThreads().filter(t=>!messageSearch||`${userName(t.partnerId)} ${t.latest.body}`.toLowerCase().includes(messageSearch));let selected=personId?threads.find(t=>t.partnerId===Number(personId)&&t.projectId===Number(projectId||0)):threads[0];
  const partner=selected?user(selected.partnerId):null,p=selected?.projectId?project(selected.projectId):null;
  return shell(`<div class="page messages-page">${pageHead(S.eyMessages,'Messages',S.messagesSub)}<div class="messages-layout"><aside class="conversation-list"><label class="sr-only" for="message-search">Search conversations</label><input class="input" id="message-search" value="${esc(messageSearch)}" placeholder="Search conversations"><div class="section-label">Recent</div>${threads.map(t=>{const u=user(t.partnerId),pr=t.projectId?project(t.projectId):null,search=`${u.name} ${t.latest.body} ${pr?.name||''}`.toLowerCase();return `<button class="conversation-item ${selected&&selected.partnerId===t.partnerId&&selected.projectId===t.projectId?'active':''}" data-message-search="${esc(search)}" data-message-thread="${t.partnerId}" data-project-context="${t.projectId||''}" title="${esc(t.latest.body)}">${avatar(u,'sm')}<span><b>${esc(u.name)}${t.unread?` <i>${t.unread}</i>`:''}</b><small>${esc(t.latest.body)}</small>${pr?`<em>${esc(project(pr.id)?.name||'Project')}</em>`:''}</span><time>${fmtTime(t.latest.created_at)}</time></button>`}).join('')||'<div class="empty">'+S.noChats+'</div>'}</aside><section class="conversation-panel">${selected&&partner?`<header><div>${avatar(partner)}<h2>${esc(partner.name)}</h2><small>${esc(partner.title)} · ${esc(partner.department)}${p?`<br>${esc(brand(p.brand_id)?.name||'')} · ${esc(p.name)}`:''}</small></div>${presence(partner)}</header><div class="message-history">${selected.items.map(m=>`<div class="message ${m.sender_id===state.currentUserId?'mine':''}"><b>${m.sender_id===state.currentUserId?'Me':esc(partner.name.split(' ')[0])}</b><p>${esc(m.body)}</p><small>${fmtDateTime(m.created_at)}</small></div>`).join('')}</div><form class="chat-compose" id="message-form" data-recipient="${partner.id}" ${p?`data-project="${p.id}"`:''}><label class="sr-only" for="message-compose-${partner.id}">Message ${esc(partner.name)}</label><textarea class="input" id="message-compose-${partner.id}" name="body" rows="2" maxlength="6000" required placeholder="Write a message…"></textarea><button class="btn primary" type="submit" aria-label="Send message">Send</button></form>`:'<div class="empty">'+S.pickChat+'</div>'}</section></div></div>`,'messages');
}

function loginView(){return `<main class="login-screen"><section class="login-card"><div class="brand-lockup"><span class="logo-mark">w</span><span>WRM <b>Operations</b></span></div><div class="eyebrow">Private beta</div><h1>${beta.passwordSetup?'Set your password':'Sign in'}</h1><form id="beta-login-form">${beta.passwordSetup?'':'<label class="label" for="beta-email">Work email</label><input class="input" id="beta-email" name="email" type="email" autocomplete="username" required>'}<label class="label" for="beta-password">Password</label><div class="password-field"><input class="input" id="beta-password" name="password" type="password" autocomplete="${beta.passwordSetup?'new-password':'current-password'}" ${beta.passwordSetup?'minlength="12"':''} required><button class="password-toggle" type="button" data-beta-password-toggle aria-controls="beta-password" aria-pressed="false">Show</button></div><div class="login-actions"><button class="btn acid">${beta.passwordSetup?'Save password':'Sign in'}</button>${beta.passwordSetup?'':'<button class="btn ghost" type="button" data-action="forgot-password">Forgot password?</button>'}</div><p id="beta-auth-error" role="alert"></p></form><small>Invitation only. Contact your beta administrator if your work email is not yet registered.</small></section></main>`;}

function previousBetaAdmin() {
  const depts=[...new Set(state.users.map(u=>u.department))];
  return shell(`<div class="page">${pageHead('Private beta','Admin','People')}<div class="notice"><b>Private beta</b> · Real accounts and shared work. ${currentUser().role==='SUPER ADMIN'?'<button class="btn acid" data-action="beta-invite">+ Invite colleague</button><button class="btn ghost" data-action="beta-export">Download data backup</button>':'Ask your administrator to invite colleagues.'}</div><div class="admin-grid"><article class="admin-card"><div class="eyebrow">Organisation</div><h2>WRM Operations Studio</h2><p>${state.users.length} people · ${depts.length} departments</p></article><article class="admin-card"><div class="eyebrow">Workflow</div><h2>Default stages</h2><p>Strategy → Copy → Design → Internal Review → CS Review → Final</p></article><article class="admin-card"><div class="eyebrow">Storage</div><h2>Private backend</h2><p>Work and files are stored in the shared beta backend.</p></article></div><div class="section-label">Departments</div><div class="cloud">${depts.map(d=>`<span class="chip">${esc(d)} · ${state.users.filter(u=>u.department===d).length}</span>`).join('')}</div><div class="section-label">Project rating guide</div><div class="grid cols-4"><div class="stat" style="--tone:#fcbe47"><div class="stat-num">A+</div><div class="stat-label">Strategic / major</div></div><div class="stat" style="--tone:#ef4754"><div class="stat-num">A</div><div class="stat-label">Important</div></div><div class="stat" style="--tone:#15adc2"><div class="stat-num">B</div><div class="stat-label">Standard</div></div><div class="stat" style="--tone:#7f8c99"><div class="stat-num">C</div><div class="stat-label">Routine</div></div></div></div>`,'admin');
}
function notFound(){return shell('<div class="page"><div class="empty"><h1>Not found</h1><button class="btn primary" data-go="home">Go home</button></div></div>');}

function render(){try{renderInner()}catch(err){console.error(err);app.innerHTML='<div class="boot">This view hit a problem.<a href="#/home">Back to Home</a></div>'}}
function renderInner() {
  if(!state.sessionUserId||beta.passwordSetup){app.innerHTML=loginView();return;}
  const [name,id,context]=route(); let html;
  if(name==='home'||!name)html=dashboard(); else if(name==='my-work')html=myWork(); else if(name==='projects')html=projectsView(); else if(name==='project')html=projectView(id); else if(name==='task')html=taskView(id); else if(name==='approvals')html=approvals(); else if(name==='brands')html=brandsView(); else if(name==='brand')html=brandView(id); else if(name==='calendar')html=calendarViewPage(); else if(name==='messages')html=messagesView(id,context); else if(name==='profile')html=profileView(); else if(name==='people')html=people(); else if(name==='admin')html=admin(); else html=notFound();
  app.innerHTML=html;
  app.querySelectorAll('a[target="_blank"]').forEach(link=>link.rel='noopener noreferrer');
  markVisibleThreadRead();
}

function modal(title,body,foot='') { modalReturnFocus=document.activeElement;modalDirty=false;document.body.classList.add('modal-open');app.inert=true;modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-head"><h2>${esc(title)}</h2><button class="close" type="button" data-action="close-modal" aria-label="Close">×</button></header><div class="modal-body">${body}</div>${foot?`<footer class="modal-foot">${foot}</footer>`:''}</section></div>`; modalRoot.querySelectorAll('.field').forEach((field,i)=>{const label=field.querySelector('label'),input=field.querySelector('input,select,textarea');if(label&&input&&!input.id){input.id=`modal-field-${i}`;label.htmlFor=input.id;}}); (modalRoot.querySelector('input,select,textarea')||modalRoot.querySelector('.close'))?.focus(); }
function closeModal(force=false){if(!modalRoot.innerHTML)return true;if(modalDirty&&!force&&!window.confirm('Discard unsaved changes?'))return false;modalDirty=false;modalRoot.innerHTML='';document.body.classList.remove('modal-open');app.inert=false;if(modalReturnFocus?.isConnected)modalReturnFocus.focus();modalReturnFocus=null;return true;}
const options=(items,selected='')=>items.map(x=>{const val=Array.isArray(x)?x[0]:x,label=Array.isArray(x)?x[1]:x;return `<option value="${esc(val)}" ${String(val)===String(selected)?'selected':''}>${esc(label)}</option>`}).join('');

function assignmentPool(){return (state.assignmentUsers||state.users).slice().sort((a,b)=>a.name.localeCompare(b.name));}
function eligibleReviewers(ownerId){return assignmentPool().filter(u=>u.id!==Number(ownerId)&&['MANAGER','TEAM LEAD','CREATIVE DIRECTOR','DEPARTMENT HEAD','CLIENT SOLUTIONS','LEADERSHIP','SUPER ADMIN'].includes(u.role));}
function openTaskForm(editId=null) {
  const t=editId?task(editId):null,defaultProject=route()[0]==='project'?Number(route()[1]):state.projects.find(p=>p.status==='Active')?.id;
  if(t) return modal('Edit task',`<form id="edit-task-form" data-task="${t.id}" class="form-grid"><div class="field full"><label class="label">Task name</label><input class="input" name="title" required value="${esc(t.title)}"></div><div class="field full"><label class="label">Brief / requirements</label><textarea name="brief" required>${esc(t.brief)}</textarea></div><div class="field"><label class="label">Owner</label><select name="ownerId">${options(assignmentPool().map(u=>[u.id,`${u.name} · ${u.department}`]),t.owner_id)}</select></div><div class="field"><label class="label">Reviewer</label><select name="reviewerId">${options(eligibleReviewers(t.owner_id).map(u=>[u.id,`${u.name} · ${u.title}`]),t.reviewer_id)}</select></div><div class="field"><label class="label">Stage</label><select name="stage">${options(project(t.project_id).workflow,t.stage)}</select></div><div class="field"><label class="label">Priority</label><select name="priority">${options(['Low','Normal','High','Urgent'],t.priority)}</select></div><div class="field full"><label class="label">Task deadline</label><input class="input" type="datetime-local" name="deadline" value="${localDateInput(t.deadline)}" required></div></form>`,`<button class="btn ghost" data-action="close-modal">Cancel</button><button class="btn primary" type="submit" form="edit-task-form">Save changes</button>`);
  const pool=isManager()?assignmentPool():[currentUser()],department=currentUser().department,owners=pool.filter(u=>u.department===department),owner=owners.find(u=>u.id===state.currentUserId)||owners[0]||currentUser(),reviewers=eligibleReviewers(owner.id);
  if(!state.projects.some(p=>p.status!=='Completed'))return modal('Create task unavailable','<div class="notice"><b>No open Project is available.</b> Create or restore a Project before adding a Task.</div>','<button class="btn primary" data-action="close-modal">Understood</button>');
  modal('Create task',`<form id="task-form" class="form-grid"><div class="field full"><label class="label">Task name *</label><input class="input" name="title" required placeholder="e.g. Write launch manifesto"></div><div class="field full"><label class="label">Brief / requirements *</label><textarea name="brief" required placeholder="What needs to be made? What must be true?"></textarea></div><div class="field"><label class="label">Project *</label><select name="projectId" required>${options(state.projects.filter(p=>p.status!=='Completed').map(p=>[p.id,`${brand(p.brand_id).name} · ${p.name}`]),defaultProject)}</select></div><div class="field"><label class="label">Department *</label><select name="department" required ${isManager()?'':'disabled'}>${options(state.departments||betaDepartments,department)}</select>${isManager()?'':'<input type="hidden" name="department" value="'+esc(department)+'">'}</div><div class="field"><label class="label">Owner *</label><select name="ownerId" required>${options(owners.map(u=>[u.id,`${u.name} · ${u.department}`]),owner.id)}</select><small>Owners are limited to the selected Department.</small></div><div class="field"><label class="label">Reviewer *</label><select name="reviewerId" required>${options(reviewers.map(u=>[u.id,`${u.name} · ${u.title}`]))}</select>${reviewers.length?'':'<small class="field-error">No eligible reviewer is available. Ask an administrator to assign a manager.</small>'}</div><div class="field"><label class="label">Stage</label><select name="stage">${options(project(defaultProject)?.workflow||[], project(defaultProject)?.workflow?.[0])}</select></div><div class="field"><label class="label">Priority</label><select name="priority">${options(['Low','Normal','High','Urgent'],'Normal')}</select></div><div class="field full"><label class="label">Task deadline *</label><input class="input" type="datetime-local" name="deadline" value="${localDateInput(Date.now()+864e5)}" required></div><div class="field full"><label class="label">Reference URL</label><input class="input" name="reference" type="url" placeholder="https://…"></div></form>`,`<button class="btn ghost" data-action="close-modal">Cancel</button><button class="btn primary" type="submit" form="task-form" ${reviewers.length?'':'disabled'}>Create task</button>`);
}

