function admin() {
  const isAdmin=currentUser().role==='SUPER ADMIN';
  const people=alphaPeople(state.users);
  const removed=state.removed||[];
  return shell(`<div class="page">${pageHead('Organisation','Admin','People, roles and Departments')}
    ${isAdmin?'<div class="toolbar"><button class="btn acid" data-action="beta-invite">+ Invite colleague</button><button class="btn ghost" data-action="beta-export">Download data backup</button></div>':''}
    <div class="section-label">Departments</div><div class="cloud">${(state.departments||[]).slice().sort().map(d=>`<span class="chip">${esc(d)} · ${people.filter(u=>u.department===d).length}</span>`).join('')}</div>
    <div class="section-label">People · ${people.length}</div><div class="admin-people">${people.map(u=>`<article class="admin-person">${avatar(u,'sm')}<div><b>${esc(u.name)}</b><small>${esc(u.email)}</small><small>${esc(u.department)} · ${esc(u.role)}</small></div><div class="admin-person-actions"><button class="btn ghost" data-person="${u.id}">Profile</button>${isAdmin?`<button class="btn ghost" data-beta-edit-person="${u.id}">Edit access</button>${u.id!==state.currentUserId?`<button class="btn ghost" data-beta-reset-password="${u.id}">Reset password</button><button class="btn danger" data-beta-remove="people" data-id="${u.id}">Remove person</button>`:''}`:''}</div></article>`).join('')}</div>
    ${isAdmin?`<div class="section-label">Removed items · ${removed.length}</div><p>Restore an item to return it to the workspace. Removing a person disables their access; their work history is retained.</p><div class="removed-list">${removed.map(r=>`<article class="removed-item"><div><b>${esc(r.name)}</b><small>${esc(r.kind==='people'?'Person':r.kind==='tasks'?'Task':r.kind==='projects'?'Project':'Brand')} · Removed ${fmtDateTime(r.deleted_at)}</small></div><button class="btn ghost" data-beta-restore="${esc(r.kind)}" data-id="${r.id}">Restore</button></article>`).join('')||'<div class="empty">No removed items.</div>'}</div>`:''}
  </div>`,'admin');
}

function openBetaRemoval(kind,id) {
  const record=(kind==='tasks'?state.tasks:kind==='projects'?state.projects:kind==='brands'?state.brands:state.users).find(x=>x.id===id);
  if(!record)return toast(S.errNotFound);
  const name=kind==='tasks'?record.title:record.name;
  let message=kind==='people'?'Their account will lose access immediately. Completed work and messages remain in history. Reassign any active Tasks and direct reports first.':kind==='projects'?`This Project and its ${projectTasks(id).length} Tasks will leave the workspace. Versions, files and activity will be retained.`:kind==='brands'?`This Brand and its Projects and Tasks will leave the workspace. Their history and files will be retained.`:'This Task will leave active lists. Its Versions, feedback, comments and history will be retained.';
  modal('Remove '+(kind==='people'?'person':kind==='projects'?'Project':kind==='brands'?'Brand':'Task'),`<h3>${esc(name)}</h3><p>${message}</p><p>You can restore it from Admin → Removed items.</p><form id="beta-remove-form" data-kind="${kind}" data-id="${id}"><label class="label" for="removal-reason">Note (optional)</label><input class="input" id="removal-reason" name="reason" maxlength="500"><p class="removal-error" role="alert"></p></form>`,`<button class="btn ghost" data-action="close-modal">Cancel</button><button class="btn danger" form="beta-remove-form">Remove ${kind==='people'?'person':kind==='tasks'?'Task':kind==='projects'?'Project':'Brand'}</button>`);
}

function openBetaPasswordReset(id){
  const u=user(id);if(!u)return toast(S.errNotFound);
  modal('Reset password · '+u.name,`<form id="beta-password-reset-form" data-id="${u.id}"><p>Create a secure, single-use recovery link for <b>${esc(u.email)}</b>. Share it only with this person.</p><p class="removal-error" role="alert"></p></form>`,`<button class="btn ghost" data-action="close-modal">Cancel</button><button class="btn primary" form="beta-password-reset-form">Create reset link</button>`);
}

function openBetaPerson(id) {
  const u=user(id);if(!u)return;
  modal('Edit access · '+u.name,`<form id="beta-person-form" data-id="${id}" class="form-grid"><div class="field full"><label class="label">Role</label><select name="role" ${u.id===state.currentUserId?'disabled':''}>${options(state.permissionRoles||[],u.role)}</select>${u.id===state.currentUserId?'<small>Your own administrator role stays unchanged.</small>':'<small>Changes apply on the colleague’s next request. Their invitation link stays valid.</small>'}</div><div class="field"><label class="label">Department</label><select name="department">${options(state.departments,u.department)}</select></div><div class="field full"><label class="label">Reports to</label><select name="managerId">${options([['','No manager'],...alphaPeople(state.users.filter(p=>p.id!==id)).map(p=>[p.id,p.name])],u.manager_id||'')}</select></div><p class="removal-error" role="alert"></p></form>`,`<button class="btn ghost" data-action="close-modal">Cancel</button><button class="btn primary" form="beta-person-form">Save changes</button>`);
}

function brandPeopleIds(b){return [...new Set([b.cs_owner_id,b.bd_owner_id,...(b.members||[])].filter(Boolean))];}
function projectPeopleIds(p){return [...new Set([...p.members,...(p.confidential?[]:brandPeopleIds(brand(p.brand_id)))])];}
function brandPeoplePanel(b){const people=alphaPeople(brandPeopleIds(b).map(id=>user(id)).filter(Boolean));return `<section class="panel brand-people"><div class="panel-head"><h2>${S.ourTeam} · ${people.length}</h2>${isManager()?`<button class="btn ghost" data-membership="brands" data-id="${b.id}">Manage people</button>`:''}</div><div class="panel-body member-summary">${people.map(u=>`<div>${personLink(u)}<small>${esc(u.department)} · ${esc(u.role)}</small></div>`).join('')||'<div class="empty">No agency people added.</div>'}</div></section>`;}
function openMembership(kind,id){
  const record=(kind==='brands'?state.brands:state.projects).find(r=>r.id===id);if(!record)return toast(S.errMissing);
  const people=alphaPeople(state.assignmentUsers||state.users),owners=kind==='brands'?[record.cs_owner_id,record.bd_owner_id].filter(Boolean):[];
  const selected=new Set([...(record.members||[]),...owners]);
  const inherited=kind==='projects'&&!record.confidential?brandPeopleIds(brand(record.brand_id)).filter(id=>!selected.has(id)).map(userName):[];
  modal((kind==='brands'?'Brand':'Project')+' people',`<h3>${esc(record.name)}</h3><p>${kind==='brands'?'Brand members can access its regular Projects. Confidential Projects need a separate invitation.':record.confidential?'Only explicit Project members can access this confidential work.':'Add people to this Project without adding them to the whole Brand.'} Actions depend on each person’s role.</p>${inherited.length?`<p class="membership-inherited"><b>Also has access through the Brand:</b> ${inherited.map(esc).join(', ')}</p>`:''}<form id="membership-form" data-kind="${kind}" data-id="${id}" data-expected="${esc(JSON.stringify(record.members||[]))}"><label class="label" for="member-search">Find a colleague</label><input class="input" id="member-search" type="search" placeholder="Name or Department"><fieldset class="member-picker"><legend>Project and Brand access</legend>${people.map(u=>`<label class="member-choice" data-member-search="${esc((u.name+' '+u.department).toLowerCase())}"><input type="checkbox" name="member" value="${u.id}" ${selected.has(u.id)?'checked':''} ${owners.includes(u.id)?'disabled':''}>${avatar(u,'sm')}<span><b>${esc(u.name)}</b><small>${esc(u.department)} · ${esc(u.role)}${owners.includes(u.id)?' · Brand owner':''}</small></span></label>`).join('')}</fieldset><p class="membership-note">Task assignments and organisational responsibilities can also grant access. Brand owners keep their access.</p><p class="removal-error" role="alert"></p></form>`,`<button class="btn ghost" data-action="close-modal">Cancel</button><button class="btn primary" form="membership-form">Save people</button>`);
}
document.addEventListener('input',e=>{if(e.target.id!=='member-search')return;const query=e.target.value.trim().toLowerCase();modalRoot.querySelectorAll('[data-member-search]').forEach(row=>{row.hidden=!row.dataset.memberSearch.includes(query);});});
document.addEventListener('click',e=>{const button=e.target.closest('[data-membership]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();if(!isManager())return toast(S.errManagers);openMembership(button.dataset.membership,Number(button.dataset.id));},true);
